/* @socom-skeleton body Open__10CZAnimMainFv */
void CZAnimMain::Open()
{
	/* 0x1c53b0 */
	if (m_IsOpen)
		Close(); /* the ELF inlines Unload and the rest of Close */

	m_version = 0x1e;
	m_gravity = -9.8f;
	m_Lod = 2; /* HIGH */
	m_search_external_nodes = false;
	m_animset_count = 0;
	m_animset_list = NULL;
	m_cmdset_count = 0;
	m_cmdset_list = NULL;
	m_UserActionAnimIndex = 0;
	m_block_activation_callback = false;

	f32 x = 0.0f;

	for (u32 i = 0; i < 41; i++)
	{
		m_inv_exp[i] = 1.0f - (expf(x) - 1.0f) / (expf(10.0f) - 1.0f);
		m_exp[i] = (expf(x) - 1.0f) / (expf(10.0f) - 1.0f);
		x += 0.25f;
	}

	InitCommands();
	NewAnimSet(2);

	m_animset_list[0].m_IsAvailable = true;
	m_animset_list[1].m_IsAvailable = true;
	m_animset_list[2].m_IsAvailable = true;

	m_CurrentFrame = 0;
	m_RunningAnimCount = 0;
	m_IsOpen = true;
}

/* @socom-skeleton body Close__10CZAnimMainFv */
bool CZAnimMain::Close()
{
	bool unloaded = Unload();

	if (_local_wildcard_str)
	{
		zfree(_local_wildcard_str);
		_local_wildcard_str = NULL;
	}

	_input_str_ptr = NULL;
	_digit_count = 0;

	if (m_NetworkPacket)
	{
		zfree(m_NetworkPacket);
		m_NetworkPacket = NULL;
	}

	m_NetworkPacketMaxSize = 0;
	m_IsOpen = false;
	m_IsStarted = false;
	
	return unloaded;
}

